import React, { useState } from "react";
import {
  FaChevronDown,
  FaChevronUp,
  FaInfoCircle,
  FaUserPlus,
} from "react-icons/fa";

const NewFAQ = () => {
  const [activeCategory, setActiveCategory] = useState(0);
  const [activeIndex, setActiveIndex] = useState(null);

  const faqData = [
    {
      category: "Doctor Appointments FAQs",
      icon: <FaInfoCircle />,
      questions: [
        {
          q: "What is 4ceps.com?",
          a: "4ceps is a healthcare platform that helps users find doctors, hospitals, clinics, diagnostic centres, and healthcare services across India. Users can compare providers and access healthcare solutions online.",
        },
        {
          q: "How can I find doctors near me on 4ceps?",
          a: "You can search by specialty, healthcare service, or location to find doctors near you. 4ceps helps you connect with healthcare professionals and medical centres based on your requirements.",
        },
        {
          q: "Can I book a doctor appointment online through 4ceps?",
          a: "Yes. 4ceps allows users to search healthcare providers and access doctor appointment booking services conveniently.",
        },
        {
          q: "How do I find the right specialist doctor?",
          a: "You can search specialists based on medical specialty, location, experience, and healthcare service requirements to find the most suitable doctor for your needs.",
        },
        {
          q: "Why choose 4ceps for healthcare services?",
          a: "4ceps offers a simple way to find doctors near you, access healthcare services, compare providers, and make informed healthcare decisions through one platform.",
        },
      ],
    },
    {
      category: "Lab Tests & Health Checkup FAQs",
      icon: <FaUserPlus />,
      questions: [
        {
          q: "Can I book lab tests online through 4ceps?",
          a: "Yes. 4ceps helps users find diagnostic centres and access lab test booking services, including preventive health screenings and routine medical tests.",
        },
        {
          q: "What healthcare services are available on 4ceps?",
          a: "4ceps provides access to doctor consultations, hospitals, clinics, diagnostic services, health checkup packages, vaccination services, medical equipment, and healthcare solutions.",
        },
        {
          q: "How can I find hospitals and clinics near me?",
          a: "Users can search hospitals and clinics by city, area, specialty, or healthcare service to find trusted healthcare providers nearby.",
        },
        {
          q: "Can I compare healthcare services before making a decision?",
          a: "Yes. Users can explore healthcare providers, services, and available options before selecting the healthcare solution that best meets their needs.",
        },
        {
          q: "Are healthcare providers listed on 4ceps verified?",
          a: "4ceps aims to connect users with trusted healthcare providers, clinics, hospitals, and diagnostic centres to help them make informed healthcare decisions.",
        },
      ],
    },
  ];

  const toggleAccordion = (index) => {
    setActiveIndex(activeIndex === index ? null : index);
  };

  const currentCategory = faqData[activeCategory];

  return (
    <section
      className="faq-section padding-b-60 pt-5 position-relative overflow-hidden"
      style={{ background: "linear-gradient(180deg, #fff 0%, #f9f7ff 100%)" }}
    >
      <div
        className="faq-bg-shape position-absolute top-0 start-0 w-100 h-100 opacity-25"
        style={{ pointerEvents: "none", zIndex: 0 }}
      >
        <div
          style={{
            position: "absolute",
            top: "5%",
            left: "-5%",
            width: "400px",
            height: "400px",
            borderRadius: "50%",
            background:
              "radial-gradient(circle, rgba(168,71,240,0.1) 0%, rgba(255,255,255,0) 70%)",
          }}
        ></div>
        <div
          style={{
            position: "absolute",
            bottom: "5%",
            right: "-5%",
            width: "500px",
            height: "500px",
            borderRadius: "50%",
            background:
              "radial-gradient(circle, rgba(113,93,242,0.1) 0%, rgba(255,255,255,0) 70%)",
          }}
        ></div>
      </div>

      <div
        className="container container-two position-relative"
        style={{ zIndex: 1 }}
      >
        <div className="section-heading text-center mb-40">
          <h6
            className="section-heading__subtitle text-main mb-3"
            style={{ letterSpacing: "2px", fontWeight: "700" }}
          >
            HAVE QUESTIONS?
          </h6>
          <h2 className="section-heading__title" style={{ fontSize: "42px" }}>
            Frequently Asked Questions
          </h2>
          <p className="mt-3 text-muted mx-auto" style={{ maxWidth: "600px" }}>
            Find answers to common questions about using 4ceps for patients and
            healthcare providers.
          </p>
        </div>

        {/* Tabs Navigation */}
        <div className="faq-tabs-container mb-4 d-flex justify-content-center align-items-center gap-3 flex-wrap">
          {faqData.map((cat, idx) => (
            <button
              key={idx}
              onClick={() => {
                setActiveCategory(idx);
                setActiveIndex(null);
              }}
              className={`faq-tab-btn d-flex align-items-center gap-2 px-4 py-2.5 rounded-pill border-0 transition-all ${
                activeCategory === idx ? "active-tab" : "bg-white shadow-sm"
              }`}
              style={{
                fontWeight: "600",
                fontSize: "15px",
                color: activeCategory === idx ? "#fff" : "#1F1A3B",
                backgroundColor:
                  activeCategory === idx ? "#A847F0" : "#fff",
                  padding: "10px 20px",
              }}
            >
              <span
                className="tab-icon"
                style={{ opacity: activeCategory === idx ? 1 : 0.6 }}
              >
                {cat.icon}
              </span>
              <span>{cat.category}</span>
            </button>
          ))}
        </div>

        <div
          className="faq-content-wrapper mx-auto"
          style={{ maxWidth: "1100px" }}
        >
          {/* Active Category Header displayed as h2 */}
          {/* <div className="category-header mb-4 text-center">
            <h2
              className="category-title"
              style={{ fontWeight: "700", color: "#1F1A3B" }}
            >
              {currentCategory.category}
            </h2>
          </div> */}

          <div className="accordion">
            {currentCategory.questions.map((item, qIdx) => {
              const index = qIdx;
              const isOpen = activeIndex === index;
              return (
                <div
                  key={qIdx}
                  className={`accordion-item mb-3 border-0 rounded-4 overflow-hidden transition-all ${
                    isOpen ? "active-item shadow" : "bg-white shadow-sm border"
                  }`}
                >
                  <button
                    className="accordion-header w-100 d-flex justify-content-between align-items-center py-3 px-4 text-start bg-transparent border-0 transition-all"
                    onClick={() => toggleAccordion(index)}
                    style={{ cursor: "pointer", outline: "none" }}
                  >
                    <span
                      className="question-text fw-bold pe-3"
                      style={{
                        color: isOpen ? "#A847F0" : "#1F1A3B",
                        fontSize: "17px",
                      }}
                    >
                      {item.q}
                    </span>
                    <span
                      className="accordion-icon rounded-circle d-flex align-items-center justify-content-center transition-all"
                      style={{
                        width: "32px",
                        height: "32px",
                        backgroundColor: isOpen ? "#A847F0" : "#f1f5f9",
                        color: isOpen ? "#fff" : "#64748b",
                        flexShrink: 0,
                      }}
                    >
                      {isOpen ? (
                        <FaChevronUp size={12} />
                      ) : (
                        <FaChevronDown size={12} />
                      )}
                    </span>
                  </button>
                  <div
                    className="accordion-content transition-all"
                    style={{
                      maxHeight: isOpen ? "1000px" : "0",
                      opacity: isOpen ? "1" : "0",
                      overflow: "hidden",
                      backgroundColor: isOpen
                        ? "rgba(168,71,240,0.02)"
                        : "transparent",
                    }}
                  >
                    <div
                      className="py-3 px-4 pt-0"
                      style={{
                        fontSize: "16px",
                        lineHeight: "1.2",
                        color: "#4b5563",
                      }}
                    >
                      {item.a}
                    </div>
                  </div>
                </div>
              );
            })}
          </div>
        </div>
      </div>

      <style
        dangerouslySetInnerHTML={{
          __html: `
                .faq-tab-btn {
                    min-width: 200px;
                    justify-content: center;
                    box-shadow: 0 4px 6px -1px rgba(0, 0, 0, 0.1), 0 2px 4px -1px rgba(0, 0, 0, 0.06);
                }
                .active-tab {
                    box-shadow: 0 4px 15px rgba(168, 71, 240, 0.3) !important;
                }
                .faq-tab-btn:hover:not(.active-tab) {
                    background-color: #f1f5f9 !important;
                }
                .transition-all {
                    transition: all 0.4s cubic-bezier(0.4, 0, 0.2, 1);
                }
                .active-item {
                    background: #ffffff !important;
                    border: 1px solid rgba(168, 71, 240, 0.1) !important;
                    transform: scale(1.005);
                }
                .accordion-item:hover:not(.active-item) {
                    transform: translateY(-2px);
                    box-shadow: 0 10px 15px -3px rgba(0, 0, 0, 0.08) !important;
                }
                .category-title {
                    font-size: 28px;
                    transition: font-size 0.3s ease;
                }
                @media (max-width: 768px) {
                    .category-title {
                        font-size: 24px;
                    }
                }
                @media (max-width: 500px) {
                    .section-heading__title {
                        font-size: 26px !important;
                    }
                    .question-text {
                        font-size: 15px !important;
                    }
                    .faq-tab-btn {
                        padding: 8px 16px !important;
                        font-size: 14px !important;
                        min-width: 100%;
                    }
                    .category-title {
                        font-size: 20px;
                    }
                }
            `,
        }}
      />
    </section>
  );
};

export default NewFAQ;
