import { Suspense, lazy, useState } from "react";
import HeaderOne from "../components/HeaderOne";
import Preloader from "../helper/Preloader";
import { SEO } from "../utils/SEO";
import NewFAQ from "../components/NewFAQ";
import UnifiedAuthModal from "../components/UnifiedAuthModal";

// Lazy loaded components (below the fold)
const PopularOne = lazy(() => import("../components/PopularOne"));
const ArrivalOne = lazy(() => import("../components/ArrivalOne"));
const ArrivalTwo = lazy(() => import("../components/ArrivalTwo"));
const SellingOne = lazy(() => import("../components/SellingOne"));
const UnifiedActionSection = lazy(() => import("../components/UnifiedActionSection"));
const SecondaryFooter = lazy(() => import("../components/SecondaryFooter"));
const PromoBanners = lazy(() => import("../components/PromoBanners"));
const MembershipBar = lazy(() => import("../components/MembershipBar"));
const ModernHero = lazy(() => import("../components/ModernHero"));
const FAQ = lazy(() => import("../components/FAQ"));
const FooterOne = lazy(() => import("../components/FooterOne"));

const HomePage = () => {
    const can = window.location.href;
    const [isLoginModalOpen, setIsLoginModalOpen] = useState(false);

  return (
    <section className="change-gradient">
      <SEO
        title="4Ceps | Trusted Healthcare Services & Medical Equipment Platform"
        description="4Ceps is your trusted healthcare platform to book hospitals, clinics & specialists online. Explore quality medical equipment and healthcare solutions."
        url={can}
      />

      <Preloader />

      <HeaderOne />

      {/* <BannerOne /> */}

      <Suspense fallback={<div style={{ minHeight: "100vh" }}></div>}>
        <ModernHero />
        <PopularOne />

        <ArrivalOne />

        <SellingOne />

        <ArrivalTwo title="Explore Healthcare Services Near You" />
        
        {/* <LoginModal 
          isOpen={isLoginModalOpen} 
          onClose={() => setIsLoginModalOpen(false)} 
        /> */}

        <PromoBanners />
        <MembershipBar />

        {/* Unified Trust & Action Section */}
        <section className="padding-b-30 pt-0">
          <div className="container container-two">
            <UnifiedActionSection onOpenLogin={() => setIsLoginModalOpen(true)} />
          </div>
        </section>

        {/* FAQ Section */}
        {/* <FAQ /> */}
        <NewFAQ/>

        {/* Global Unified Auth Modal for HomePage */}
        <UnifiedAuthModal 
          isOpen={isLoginModalOpen} 
          onClose={() => setIsLoginModalOpen(false)} 
        />

        {/* FooterOne */}
        <SecondaryFooter />
        <FooterOne />
      </Suspense>
    </section>
  );
};

export default HomePage;
